registerEnglish([["Ezra",1,1,"Now in the first year of Cyrus king of Persia, that the word of the Lord by the mouth of Jeremiah might be fulfilled, the Lord stirred up the spirit of Cyrus king of Persia, that he made a proclamation throughout all his kingdom, and put it also in writing, saying,"],["Ezra",1,2,"Thus says Cyrus king of Persia, The Lord God of heaven has given me all the kingdoms of the earth; and he has charged me to build him a house at Jerusalem, which is in Judah."],["Ezra",1,3,"Whoever is among you of all his people, let his God be with him, and let him go up to Jerusalem, which is in Judah, and build the house of the Lord God of Israel; (he is the God,) which is in Jerusalem."],["Ezra",1,4,"And whoever remains in any place where he sojourns, let the men of his place help him with silver, and with gold, and with goods, and with beasts, besides the freewill offering for the house of God that is in Jerusalem."],["Ezra",1,5,"Then rose up the chiefs of the fathers' houses of Judah and Benjamin, and the priests, and the Levites, with all them whose spirit God had stirred to go up to build the house of the Lord which is in Jerusalem."],["Ezra",1,6,"And all they who were about them strengthened their hands with vessels of silver, with gold, with goods, and with beasts, and with precious things, besides all that was willingly offered."],["Ezra",1,7,"Also Cyrus the king brought forth the vessels of the house of the Lord, which Nebuchadnezzar had brought out of Jerusalem, and had put them in the house of his gods;"],["Ezra",1,8,"those did Cyrus king of Persia bring out by the hand of Mithredath the treasurer, and counted them out to Sheshbazzar, the prince of Judah."],["Ezra",1,9,"And this is the number of them: thirty basins of gold, a thousand basins of silver, twenty nine knives,"],["Ezra",1,10,"thirty bowls of gold, silver bowls of a second sort four hundred and ten, and other vessels a thousand."],["Ezra",1,11,"And the vessels of gold and of silver were five thousand four hundred. All these did Sheshbazzar bring, when the exiles were brought up from Babylon to Jerusalem."],["Ezra",2,1,"Now these are the children of the province who went up out of the captivity, of those exiles whom Nebuchadnezzar the king of Babylon had carried away to Babylon, and they came back to Jerusalem and Judah, everyone to his city."],["Ezra",2,2,"They came with Zerubbabel, Jeshua, Nehemiah, Seraiah, Reelaiah, Mordechai, Bilshan, Mispar, Bigvai, Rehum, and Baanah. The number of the men of the children of Israel:"],["Ezra",2,3,"the children of Parosh, two thousand one hundred and seventy two."],["Ezra",2,4,"The children of Shephatiah, three hundred and seventy two."],["Ezra",2,5,"The children of Arah, seven hundred and seventy five."],["Ezra",2,6,"The children of Pahath-moab, of the children of Jeshua and Joab, two thousand eight hundred and twelve."],["Ezra",2,7,"The children of Elam, one thousand two hundred and fifty four."],["Ezra",2,8,"The children of Zattu, nine hundred and forty five."],["Ezra",2,9,"The children of Zaccai, seven hundred and sixty."],["Ezra",2,10,"The children of Bani, six hundred and forty two."],["Ezra",2,11,"The children of Bebai, six hundred and twenty three."],["Ezra",2,12,"The children of Azgad, one thousand two hundred and twenty two."],["Ezra",2,13,"The children of Adonikam, six hundred and sixty six."],["Ezra",2,14,"The children of Bigvai, two thousand and fifty six."],["Ezra",2,15,"The children of Adin, four hundred and fifty four."],["Ezra",2,16,"The children of Ater (of Jehizkiah,) ninety eight."],["Ezra",2,17,"The children of Bezai, three hundred and twenty three."],["Ezra",2,18,"The children of Jorah, a hundred and twelve."],["Ezra",2,19,"The children of Hashum, two hundred and twenty three."],["Ezra",2,20,"The children of Gibbar, ninety five."],["Ezra",2,21,"The children of Beth-lehem, one hundred and twenty three."],["Ezra",2,22,"The men of Netophah, fifty six."],["Ezra",2,23,"The men of Anathoth, one hundred and twenty eight."],["Ezra",2,24,"The children of Azmaveth, forty two."],["Ezra",2,25,"The children of Kirjath-arim, Chephirah, and Beeroth, seven hundred and forty three."],["Ezra",2,26,"The children of Ramah and Geba, six hundred and twenty one."],["Ezra",2,27,"The men of Michmas, one hundred and twenty two."],["Ezra",2,28,"The men of Beth-el and Ai, two hundred and twenty three."],["Ezra",2,29,"The children of Nebo, fifty two."],["Ezra",2,30,"The children of Magbish, one hundred and fifty six."],["Ezra",2,31,"The children of the other Elam, one thousand two hundred and fifty four."],["Ezra",2,32,"The children of Harim, three hundred and twenty."],["Ezra",2,33,"The children of Lod, Hadid, and Ono, seven hundred and twenty five."],["Ezra",2,34,"The children of Jericho, three hundred and forty five."],["Ezra",2,35,"The children of Senaah, three thousand six hundred and thirty."],["Ezra",2,36,"The priests: the children of Jedaiah of the houses of Jeshua, nine hundred and seventy three."],["Ezra",2,37,"The children of Immer, one thousand and fifty two."],["Ezra",2,38,"The children of Pashur, one thousand two hundred and forty seven."],["Ezra",2,39,"The children of Harim, one thousand and seventeen."],["Ezra",2,40,"The Levites: the children of Jeshua and Kadmiel of the children of Hodaviah, seventy four."],["Ezra",2,41,"The singers: the children of Asaph, one hundred and twenty eight."],["Ezra",2,42,"The children of the gatekeepers: the children of Shallum, the children of Ater, the children of Talmon, the children of Akkub the children of Hatita, the children of Shobab, in all, one hundred and thirty nine."],["Ezra",2,43,"The temple servants; the children of Ziha, the children of Hasupha, and the children of Tabbaoth,"],["Ezra",2,44,"the children of Keros, the children of Siaha, the children of Padon,"],["Ezra",2,45,"the children of Lebanah, the children of Hagabah, the children of Akkub,"],["Ezra",2,46,"the children of Hagab, the children of Shalmai, the children of Hanan,"],["Ezra",2,47,"the children of Giddel, the children of Gahar, the children of Reaiah,"],["Ezra",2,48,"the children of Rezin, the children of Nekoda, the children of Gazzam,"],["Ezra",2,49,"the children of Uzza, the children of Paseah, the children of Besai,"],["Ezra",2,50,"the children of Asnah, the children of Mehunim, the children of Nephusim,"],["Ezra",2,51,"the children of Bakbuk, the children of Hakupha, the children of Harhur,"],["Ezra",2,52,"the children of Bazluth, the children of Mehida, the children of Harsha,"],["Ezra",2,53,"the children of Barkos, the children of Sisera, the children of Thamah,"],["Ezra",2,54,"the children of Neziah, the children of Hatipha."],["Ezra",2,55,"The children of the servants of Solomon: the children of Sotai, the children of Sophereth, the children of Peruda,"],["Ezra",2,56,"the children of Jaalah, the children of Darkon, the children of Giddel,"],["Ezra",2,57,"the children of Shephatiah, the children of Hattil, the children of Pochereth, the children of Ami."],["Ezra",2,58,"All the temple servants, and the children of the servants of Solomon were three hundred and ninety two."],["Ezra",2,59,"And these were they who went up from Tel-melah, Tel-harsa, Cherub, Addan, and Immer, but they could not tell their father's house, and their seed, whether they were of Israel:"],["Ezra",2,60,"the children of Delaiah, the children of Tobiah, the children of Nekoda, six hundred and fifty two."],["Ezra",2,61,"And of the children of the priests: the children of Habaiah, the children of Hakkoz; the children of Barzillai, who took a wife of the daughters of Barzillai the Gileadite, and was called after their name:"],["Ezra",2,62,"these sought their register among those who were reckoned by genealogy, but they were not found: therefore they were excluded from the priesthood as unfit."],["Ezra",2,63,"And the governor said to them, that they should not eat of the most holy things, till there stood up a priest with Urim and with Thummim."],["Ezra",2,64,"The whole congregation together was forty two thousand three hundred and sixty,"],["Ezra",2,65,"besides their men servants and women servants, of whom there were seven thousand three hundred and thirty seven: and there were among them two hundred singing men and singing women."],["Ezra",2,66,"Their horses were seven hundred and thirty six; their mules, two hundred and forty five;"],["Ezra",2,67,"their camels, four hundred and thirty five; their asses, six thousand seven hundred and twenty."],["Ezra",2,68,"And some of the chiefs of fathers' houses, when they came to the house of the Lord which is at Jerusalem, offered freely for the house of God to set it up in its place:"],["Ezra",2,69,"they gave after their ability to the treasury of the work sixty one thousand drachmas of gold, and five thousand minas of silver, and one hundred priests' garments."],["Ezra",2,70,"So the priests, and the Levites, and some of the people, and the singers, and the gatekeepers, and the temple servants, dwelt in their cities, and all Israel in their cities."],["Ezra",3,1,"And when the seventh month was come, and the children of Israel were in the cities, the people gathered themselves together as one man to Jerusalem."],["Ezra",3,2,"Then stood up Jeshua the son of Jozadak, and his brethren the priests, and Zerubbabel the son of Shealtiel, and his brethren, and they built the altar of the God of Israel, to offer burnt offerings upon it, as it is written in the law of Moses the man of God."],["Ezra",3,3,"And they set the altar upon its bases; for fear was upon them because of the people of those countries: and they offered burnt offerings upon it to the Lord, burnt offerings morning and evening."],["Ezra",3,4,"And they kept the feast of booths, as it is written, and offered the daily burnt offerings by number, according to the prescribed form, as the duty of every day required;"],["Ezra",3,5,"and afterwards they offered the continual burnt offering, both of the new moons, and of all the sacred appointed seasons of the Lord, and on behalf of everyone who willingly offered a free will offering to the Lord."],["Ezra",3,6,"From the first day of the seventh month they began to offer burnt offerings to the Lord. But the foundation of the temple of the Lord was not yet laid."],["Ezra",3,7,"They gave money also to the masons, and to the carpenters; and food, and drink, and oil, to those of Zidon, and of Tyre, to bring cedar trees from the Lebanon to the sea of Japho, according to the grant that they had from Cyrus king of Persia."],["Ezra",3,8,"Now in the second year of their coming to the house of God at Jerusalem, in the second month, began Zerubbabel the son of Shealtiel, and Jeshua the son of Jozadak, and the remnant of their brethren the priests and the Levites, and all they who were come out of the captivity to Jerusalem; and appointed the Levites, from twenty years old and upwards, to superintend the work of the house of the Lord."],["Ezra",3,9,"Then stood Jeshua with his sons and his brethren, Qadmi'el and his sons, the sons of Judah, together, to superintend the workmen in the house of God: the sons of Henadad, with their sons and their brethren the Levites."],["Ezra",3,10,"And when the builders laid the foundation of the temple of the Lord, they set the priests in their apparel with trumpets, and the Levites the sons of Asaph with cymbals, to praise the Lord, according to the form prescribed by David king of Israel."],["Ezra",3,11,"And they sang responsively in praising and giving thanks to the Lord; because he is good, for his steadfast love endures for ever towards Israel. And all the people shouted with a great shout, when they praised the Lord, because the foundation of the house of the Lord was laid."],["Ezra",3,12,"But many of the priests and Levites and the chiefs of the fathers' houses, old men who had seen the first house; when the foundation of this house was laid before their eyes, wept with a loud voice; but many shouted aloud for joy:"],["Ezra",3,13,"so that the people could not distinguish the sound of the shout of joy from the sound of the weeping of the people: for the people shouted with a loud shout, and the sound was heard afar off."],["Ezra",4,1,"Now when the adversaries of Judah and Benjamin heard that the children of the exiles were building the temple to the Lord God of Israel;"],["Ezra",4,2,"then they came to Zerubbabel, and to the chiefs of the fathers' houses and said to them, Let us build with you: for we seek your God, as you do; and we have sacrificed to him since the days of Esar-haddon king of Assyria, who brought us up here."],["Ezra",4,3,"But Zerubbabel and Jeshua, and the rest of the chiefs of the fathers' houses of Israel, said to them, You have nothing to do with us in building a house to our God; but we ourselves alone will build to the Lord God of Israel, as king Cyrus the king of Persia has commanded us."],["Ezra",4,4,"Then the people of the land weakened the hands of the people of Judah, and frightened them off from building,"],["Ezra",4,5,"and they hired counsellors against them, to frustrate their purpose, all the days of Cyrus king of Persia, until the reign of Darius king of Persia."],["Ezra",4,6,"And in the reign of Ahasuerus, in the beginning of his reign, they wrote to him an accusation against the inhabitants of Judah and Jerusalem."],["Ezra",4,7,"And in the days of Artaxerxes, Bishlam, Mithredath, Tabeel, and the rest of their companions, wrote to Artaxerxes, king of Persia; and the writing of the letter was written in the Aramic script, and translated into the Aramic tongue."],["Ezra",4,8,"Rehum the chancellor and Shimshai the scribe wrote a letter against Jerusalem to Artaxerxes the king in this sort:"],["Ezra",4,9,"then wrote Rehum the chancellor, and Shimshai the scribe, and the rest of their companions; the Dinaites, the Apharsathchites, the Tarpelites, the Apharsites, the Archevites, the Elamites, the Susanchites, the Dehavites, the Elamites,"],["Ezra",4,10,"and the rest of the nations whom the great and noble Asnappar brought over, and placed in the cities of Samaria, and the rest who are on this side of the river. And now,"],["Ezra",4,11,"this is the copy of the letter that they sent to him, to Artaxerxes the king; Thy servants the men on this side of the river. And now,"],["Ezra",4,12,"Be it known to the king, that the Jews who came up from thee to us are come to Jerusalem; they are building the rebellious and the bad city, and have set up its walls, and joined the foundations."],["Ezra",4,13,"Be it known now to the king, that, if this city is built, and the walls set up again, then they will not pay toll, tribute, and custom, and so the revenue of the kings will suffer damage."],["Ezra",4,14,"Now because we feel closely bound to the king's palace, and it was not meet for us to see the king's dishonour, therefore we have sent and certified the king;"],["Ezra",4,15,"that search may be made in the book of the records of thy fathers: so shalt thou find in the book of the records, and know that this city is a rebellious city, and hurtful to kings and provinces, and that they have moved sedition within the same of old time: for which cause was this city laid waste."],["Ezra",4,16,"We make known to the king that, if this city is rebuilt and its walls set up, by this means thou shalt have no portion on this side of the river."],["Ezra",4,17,"Then the king sent an answer to Rehum the chancellor, and to Shimshai the scribe, and to the rest of their companions who dwelt in Samaria, and to the rest beyond the river. Peace. And now,"],["Ezra",4,18,"the letter which you sent to us has been plainly read before me."],["Ezra",4,19,"And I commanded, and search has been made, and it is found that this city of old time made insurrection against kings, and that rebellion and sedition were made in it."],["Ezra",4,20,"And there have been mighty kings over Jerusalem, who ruled over all countries beyond the river; and toll, tribute, and custom, was paid to them."],["Ezra",4,21,"Therefore make a decree to cause these men to cease, and that this city be not rebuilt, until a further decree is given from me."],["Ezra",4,22,"Take heed now not to be slack in this: why should damage grow to the hurt of the kings?"],["Ezra",4,23,"Now when the copy of king Artaxerxes's letter was read before Rehum, and Shimshai the scribe, and their companions, they went up in haste to Jerusalem to the Jews, and made them to cease by force and power."],["Ezra",4,24,"Then the work of the house of God which is at Jerusalem ceased. So it ceased until the second year of the reign of Darius king of Persia."],["Ezra",5,1,"Then the prophets, Haggai the prophet, and Zechariah the son of Iddo, prophesied to the Jews who were in Judah and Jerusalem in the name of the God of Israel, even to them."],["Ezra",5,2,"Then rose up Zerubbabel the son of Shealtiel, and Jeshua the son of Jozadak, and began to build the house of God which is at Jerusalem: and with them were the prophets of God helping them."],["Ezra",5,3,"At the same time came to them Tatnai, governor on this side of the river, and Shethar-boznai, and their companions, and said thus to them, Who has commanded you to build this house, and to make up this wall?"],["Ezra",5,4,"We then spoke to them after this manner: What are the names of the men who are engaged on this building?"],["Ezra",5,5,"But the eye of their God was upon the elders of the Jews, that they could not cause them to cease, till the matter came to Darius: and then they returned answer by letter concerning this matter."],["Ezra",5,6,"The copy of the letter that Tatnai, governor on this side of the river, and Shethar-boznai, and his companions the Apharsachites, who were on this side of the river, sent to Darius the king:"],["Ezra",5,7,"they sent a letter to him, and in it was written thus; To Darius the king, all peace."],["Ezra",5,8,"Be it known to the king, that we went into the province of Judah, to the house of the great God, which is built with great stones, and timber is laid in the walls, and this work goes on with diligence, and prospers in their hands."],["Ezra",5,9,"Then we asked those elders, and said to them thus, Who commanded you to build this house, and to make up these walls?"],["Ezra",5,10,"We asked their names also, to make known to thee, that we might write the names of the men who were at their head."],["Ezra",5,11,"And thus they returned us answer, saying, We are the servants of the God of heaven and earth, and build the house that was built these many years ago, which a great king of Israel did build and set up."],["Ezra",5,12,"But because our fathers had provoked the God of heaven to anger, he gave them into the hand of Nebuchadnezzar the king of Babylon, the Chaldean, who destroyed this house, and carried the people away into Babylon."],["Ezra",5,13,"But in the first year of Cyrus the king of Babylon the same king Cyrus made a decree to build this house of God."],["Ezra",5,14,"And also the vessels of gold and silver of the house of God, which Nebuchadnezzar took out of the temple that was in Jerusalem, and brought into the temple of Babylon, these did Cyrus the king take out of the temple of Babylon, and they were delivered to one, whose name was Sheshbazzar, whom he had made governor;"],["Ezra",5,15,"and he said to him, Take these vessels, go, carry them into the temple that is in Jerusalem, and let the house of God be built on its place."],["Ezra",5,16,"Then came the same Sheshbazzar, and laid the foundation of the house of God which is in Jerusalem: and since that time even until now it has been in building, and it is still not finished."],["Ezra",5,17,"Now therefore, if it seem good to the king, let search be made in the king's treasure house, which is there at Babylon, whether it be so, that a decree was made by Cyrus the king to build this house of God at Jerusalem, and let the king send his pleasure to us concerning this matter."],["Ezra",6,1,"Then Darius the king made a decree, and search was made in the house of the archives, where the treasures were laid up in Babylon."],["Ezra",6,2,"And there was found at Ahmeta, the fortress that is in the province of Medes, a roll, and therein was a record thus written:"],["Ezra",6,3,"In the first year of Cyrus the king, the same Cyrus the king made a decree, Concerning the house of God at Jerusalem; let the house be built, the place where they offer sacrifices, and let its foundations be strongly laid; its height sixty cubits, and its breadth sixty cubits;"],["Ezra",6,4,"with three rows of great stones, and a row of new timber: and let the expenses be paid out of the king's house:"],["Ezra",6,5,"and also let the golden and silver vessels of the house of God which Nebuchadnezzar took out of the temple which is at Jerusalem, and brought to Babylon, be restored, and brought back to the temple which is at Jerusalem, every one to its place, and place them in the house of God."],["Ezra",6,6,"Now Tatnai, governor beyond the river, Shethar-boznai, and your associates, the Apharsachites, who are beyond the river, keep far from hence:"],["Ezra",6,7,"let the work of this house of God alone; let the governor of the Jews and the elders of the Jews build this house of God in its place."],["Ezra",6,8,"Moreover I make a decree as to what you shall do for the elders of these Jews for the building of this house of God: that of the king's goods, even of the tribute beyond the river, expenses be given with all diligence to these men so that they are not delayed."],["Ezra",6,9,"And that which they have need of, both young bullocks, and rams, and lambs, for the burnt offerings of the God of heaven, wheat, salt, wine and oil, according to the word of the priests who are at Jerusalem, let it be given them day by day without fail:"],["Ezra",6,10,"that they may offer sacrifices of sweet savour to the God of heaven, and pray for the life of the king, and of his sons."],["Ezra",6,11,"Also I have made a decree, that whoever shall alter this word, let a beam of a timber be pulled down from his house, and let him be lifted up and impaled thereon; and let his house be made a dunghill for this."],["Ezra",6,12,"And may the God who has caused his name to dwell there destroy all kings and peoples, that shall put to their hand to alter this, or to destroy this house of God which is at Jerusalem. I Darius have made a decree; let it be done with diligence."],["Ezra",6,13,"Then Tatnai governor on this side of the river, Shethar-boznai, and their associates, according to that which Darius the king had sent, so they did with diligence."],["Ezra",6,14,"And the elders of the Jews built, and they prospered through the prophesying of Haggai the prophet and Zechariah the son of Iddo. And they built, and finished it, according to the commandment of the God of Israel, and according to the commandment of Cyrus, and Darius, and Artaxerxes king of Persia."],["Ezra",6,15,"And this house was finished on the third day of the month Adar, which was in the sixth year of the reign of Darius the king."],["Ezra",6,16,"And the children of Israel, the priests and the Levites, and the rest of the children of the exile, kept the dedication of this house of God with joy,"],["Ezra",6,17,"and they offered at the dedication of this house of God a hundred bullocks, two hundred rams, four hundred lambs; and for a sin offering for all Israel, twelve he goats, according to the number of the tribes of Israel."],["Ezra",6,18,"And they set the priests in their divisions, and the Levites in their courses, for the service of God, which is at Jerusalem; as it is written in the book of Moses."],["Ezra",6,19,"And the children of the exile kept the passover upon the fourteenth day of the first month."],["Ezra",6,20,"For the priests and the Levites had purified themselves; all of them were pure; and they killed the passover lamb for all the children of the exile, and for their brethren the priests, and for themselves."],["Ezra",6,21,"And the children of Israel who were come back out of exile, and all such as had separated themselves to them from the filthiness of the nations of the land, to seek the Lord God of Israel did eat of it."],["Ezra",6,22,"And they kept the feast of unleavened bread seven days with joy: for the Lord had made them joyful, and turned the heart of the king of Assyria to them, to strengthen their hands in the work of the house of God, the God of Israel."],["Ezra",7,1,"Now after these things, in the reign of Artaxerxes king of Persia, Ezra the son of Seraiah, the son of Azariah, the son of Hilkiah,"],["Ezra",7,2,"the son of Shallum, the son of Zadok, the son of Ahitub,"],["Ezra",7,3,"the son of Amariah, the son of Azariah, the son of Meraioth,"],["Ezra",7,4,"the son of Zerahiah, the son of Uzzi, the son of Bukki,"],["Ezra",7,5,"the son of Abishua, the son of Phinehas, the son of Eleazar, the son of Aaron the chief priest: –"],["Ezra",7,6,"this Ezra went up from Babylon; and he was a ready scribe in the law of Moses, which the Lord God of Israel had given: and the king granted him all his request, according to the hand of the Lord his God upon him."],["Ezra",7,7,"And there went up some of the children of Israel, and of the priests, and the Levites, and the singers, and the gatekeepers, and the temple servants, to Jerusalem, in the seventh year of Artaxerxes the king."],["Ezra",7,8,"And he came to Jerusalem in the fifth month, which was in the seventh year of the king."],["Ezra",7,9,"For upon the first day of the first month was the beginning of the going up from Babylon, and on the first day of the fifth month he came to Jerusalem, according to the good hand of his God upon him."],["Ezra",7,10,"For Ezra had prepared his heart to seek the law of the Lord, and to do it, and to teach in Israel statutes and judgments."],["Ezra",7,11,"Now this is the copy of the letter that the king Artaxerxes gave to Ezra the priest, the scribe, learned in the words of the commandments of the Lord, and of his statutes to Israel."],["Ezra",7,12,"Artaxerxes, king of kings, to Ezra the priest, a scribe of the law of the God of heaven, a perfect man. And now,"],["Ezra",7,13,"I make a decree, that all they of the people of Israel, and of his priests and Levites, in my realm, who are minded of their own freewill to go up to Jerusalem, may go with thee."],["Ezra",7,14,"For thou art sent by the king, and by his seven counsellors, to inquire concerning Judah and Jerusalem, according to the law of thy God which is in thy hand;"],["Ezra",7,15,"and to carry the silver and gold, which the king and his counsellors have freely offered to the God of Israel, whose habitation is in Jerusalem,"],["Ezra",7,16,"and all the silver and gold that thou canst find in all the province of Babylon, with the freewill offering of the people, and of the priests, offering willingly for the house of their God which is in Jerusalem:"],["Ezra",7,17,"that thou mayst buy speedily with this money bullocks, rams, lambs, with their meal offerings and their drink offerings, and offer them upon the altar of the house of your God which is in Jerusalem."],["Ezra",7,18,"And whatever shall seem good to thee, and to thy brethren, to do with the rest of the silver and the gold, that do after the will of your God."],["Ezra",7,19,"And the vessels that are given thee for the service of the house of thy God, deliver before the God of Jerusalem."],["Ezra",7,20,"And what more shall be needful for the house of thy God, which thou shalt have occasion to bestow, bestow it out of the king's treasure house."],["Ezra",7,21,"And I, even I Artaxerxes the king, do make a decree to all the treasurers who are beyond the river, that whatever Ezra the priest, the scribe of the law of the God of heaven, shall require of you, it be done with diligence,"],["Ezra",7,22,"up to a hundred talents of silver, and up to a hundred measures of wheat, and up to a hundred bats of wine, and up to a hundred bats of oil, and salt without prescribed limit."],["Ezra",7,23,"Whatever is commanded by the God of heaven, let it be speedily done for the house of the God of heaven: for why should there be wrath against the realm of the king and his sons?"],["Ezra",7,24,"We also notify you, that as regards any of the priests and Levites, singers, gatekeepers, servants, or ministers of this house of God, it shall not be lawful to impose toll, tribute, or custom, upon them."],["Ezra",7,25,"And thou, Ezra, after the wisdom of thy God, that is in thy hand, appoint magistrates and judges, who may judge all the people that are beyond the river, all such as know the laws of thy God; and teach them who do not know them."],["Ezra",7,26,"And whoever will not do the law of thy God, and the law of the king, let judgment be with diligence executed upon him, whether it be for death, or for banishment, or for confiscation of goods, or for imprisonment."],["Ezra",7,27,"Blessed be the Lord God of our fathers, which has put such a thing as this in the king's heart, to beautify the house of the Lord which is in Jerusalem:"],["Ezra",7,28,"and has given me grace before the king, and his counsellors, and before all the king's mighty princes. And I was strengthened as the hand of the Lord my God was upon me, and I gathered together out of Israel chief men to go up with me."],["Ezra",8,1,"Now these are the heads of their fathers' houses, and this is the genealogy of those who went up with me from Babylon, in the reign of Artaxerxes the king."],["Ezra",8,2,"Of the sons of Phinehas, Gershom: of the sons of Ithamar, Daniel: of the sons of David, Hattush:"],["Ezra",8,3,"of the sons of Shechaniah, of the sons of Parosh, Zechariah; and with him were reckoned by genealogy one hundred and fifty males."],["Ezra",8,4,"Of the sons of Pahath-moab, Elihoenai the son of Zerahiah; and with him two hundred males."],["Ezra",8,5,"Of the sons of Shechaniah, the son of Jahaziel and with him three hundred males."],["Ezra",8,6,"And of the sons of Adin, Ebed the son of Jonathan; and with him fifty males."],["Ezra",8,7,"And of the sons of Elam, Jeshaiah the son of Athaliah; and with him seventy males."],["Ezra",8,8,"And of the sons of Shephatiah, Zebadiah the son of Michael; and with him eighty males."],["Ezra",8,9,"Of the sons of Joab, Obadiah the son of Jehiel; and with him two hundred and eighteen males."],["Ezra",8,10,"And of the sons of Shelomith, the son of Josiphiah; and with him one hundred and sixty males."],["Ezra",8,11,"And of the sons of Bebai, Zechariah the son of Bebai: and with him twenty eight males."],["Ezra",8,12,"And of the sons of Azgad, Johanan the son of Hakkatan; and with him a hundred and ten males."],["Ezra",8,13,"And of the sons of Adonikam (who came in the rear,) these were their names: Eliphelet, Jeiel, and Shemaiah; and with them were sixty males."],["Ezra",8,14,"And of the sons of Bigvai, Utai and Zaccur; and with them were seventy males."],["Ezra",8,15,"And I gathered them together at the river that runs to Ahava, and we encamped there for three days: and I inspected the people, and the priests, but found there none of the sons of Levi."],["Ezra",8,16,"So I sent for Eliezer, for Ariel, for Shemaiah, and for Elnathan, and for Joiarib, and for Elnathan, and for Nathan, and for Zechariah, and for Meshullam, chief men: and for Joiarib, and for Elnathan, men of understanding."],["Ezra",8,17,"And I sent them with commandment to Iddo the chief at the place Casiphia, and I told them what they should say to Iddo, and to his brother who were appointed at the place Casiphia that they should bring to us ministers for the house of God."],["Ezra",8,18,"And by the good hand of our God upon us they brought us a man of discretion, of the sons of Mahli, the son of Levi, the son of Israel; and Sherebiah, with his sons and his brothers, eighteen;"],["Ezra",8,19,"and Hashabiah, and with him Jeshaiah of the sons of Merari, his brethren and their sons, twenty;"],["Ezra",8,20,"also of the temple servants, whom David and the princes had appointed for the service of the Levites, two hundred and twenty temple servants; all of whom were mentioned by name."],["Ezra",8,21,"Then I proclaimed a fast there, at the river of Ahava, that we might afflict ourselves before our God, to seek of him a safe journey for us, and for our little ones, and for all our substance."],["Ezra",8,22,"For I was ashamed to ask of the king a band of soldiers and horsemen to help us against the enemy on the road: because we had spoken to the king, saying, The hand of our God is upon all those who seek him for good; but his power and his wrath are against all those who forsake him."],["Ezra",8,23,"So we fasted and besought our God for this: and he listened to our entreaty."],["Ezra",8,24,"Then I separated twelve of the chief of the priests, Sherebiah, Hashabiah, and ten of their brethren with them,"],["Ezra",8,25,"and weighed to them the silver, and the gold, and the vessels, the offering of the house of our God, which the king, and his counsellors, and his lords, and all Israel there present, had offered:"],["Ezra",8,26,"so I weighed into their hand six hundred and fifty talents of silver, and of silver vessels a hundred talents, and of gold a hundred talents;"],["Ezra",8,27,"also twenty bowls of gold, of a thousand darics; and two vessels of fine copper, precious as gold."],["Ezra",8,28,"And I said to them, You are holy to the Lord; the vessels are holy also; and the silver and the gold are a freewill offering to the Lord God of your fathers."],["Ezra",8,29,"Watch, and keep them, until you weigh them before the chief of the priests and the Levites, and chief of the fathers of Israel, at Jerusalem, in the chambers of the house of the Lord."],["Ezra",8,30,"So the priests and the Levites took the weight of the silver, and the gold, and the vessels, to bring them to Jerusalem to the house of our God."],["Ezra",8,31,"Then we departed from the river of Ahava on the twelfth day of the first month, to go to Jerusalem: and the hand of our God was upon us, and he delivered us from the hand of the enemy, and of such as lie in wait by the way."],["Ezra",8,32,"And we came to Jerusalem, and abode there three days."],["Ezra",8,33,"Now on the fourth day the silver and the gold and the vessels were weighed in the house of our God by the hand of Meremoth the son of Uriah the priest; and with him was Eleazar the son of Phinehas; and with them was Jozabad the son of Jeshua, and Noadiah the son of Binnui, Levites;"],["Ezra",8,34,"the whole was counted and weighed: and the weight of everything was recorded at that time."],["Ezra",8,35,"Also the children of those who had been carried away, who were come out of the exile, offered burnt offerings to the God of Israel, twelve bullocks for all Israel, ninety six rams, seventy seven lambs, twelve he goats for a sin offering: all this was a burnt offering to the Lord."],["Ezra",8,36,"And they delivered the king's commissions to the king's satraps, and to the governors on this side of the river: and they furthered the people, and the house of God."],["Ezra",9,1,"Now when these things were done, the princes came to me, saying, The people of Israel, and the priests, and the Levites, have not separated themselves from the peoples of the lands, doing according to their abominations, even of the Canaanite, the Hittite, the Perizzite, the Jebusite, the Ammonite, the Moabite, the Egyptian, and the Amorite."],["Ezra",9,2,"For they have taken of their daughters for themselves, and for their sons: so that the holy seed have mingled themselves with the peoples of those lands: indeed, the hand of the princes and rulers has been chief in this crime."],["Ezra",9,3,"And when I heard this thing, I rent my garment and my mantle, and plucked off the hair of my head and of my beard, and sat down appalled."],["Ezra",9,4,"Then everyone who trembled at the words of the God of Israel, because of the transgression of those who had been carried away gathered around me; and I sat appalled until the evening sacrifice."],["Ezra",9,5,"And at the evening sacrifice I arose from my fasting; and my garment and my mantle being rent, I fell upon my knees, and spread out my hands to the Lord my God,"],["Ezra",9,6,"and said, O my God, I am ashamed and blush to lift up my face to Thee, my God: for our iniquities are increased over our head, and our guilt has mounted to the heavens."],["Ezra",9,7,"Since the days of our fathers we have been exceedingly guilty to this day; and for our iniquities we, our kings, and our priests, have been delivered into the hand of the kings of the lands, to the sword, to captivity, and to plundering, and to utter shame, as it is this day."],["Ezra",9,8,"And now for a little moment grace has been shown by the Lord our God, to leave us a remnant to escape, and to give us a secure anchorage in his holy place, that our God may lighten our eyes, and give us a little reviving in our bondage."],["Ezra",9,9,"For we were slaves; yet our God did not forsake us in our slavery but gave us grace in the sight of the kings of Persia; to give us a reviving, to set up the house of our God, and to repair its ruins, and to give us a wall in Judah and in Jerusalem."],["Ezra",9,10,"And now, O our God, what shall we say after this? for we have forsaken Thy commandments,"],["Ezra",9,11,"which Thou hast commanded by Thy servants the prophets, saying, The land, into which you go to possess it, is an unclean land through the uncleanness of the peoples of the lands, with their abominations, for they have filled it from one end to the other with their uncleanness."],["Ezra",9,12,"Now therefore do not give your daughters to their sons, nor take their daughters to your sons, nor seek their peace or their welfare for ever: that you may be strong, and eat the good of the land, and leave it for an inheritance to your children for ever."],["Ezra",9,13,"And after all that which has come upon us for our evil deeds, and for our great guilt, seeing that Thou our God hast punished us less than our iniquities deserve, and hast given us such deliverance as this;"],["Ezra",9,14,"should we again break Thy commandments, and make marriages with the peoples of these abominations? wouldst Thou not be angry with us till Thou wouldst consume us, so that there should be no remnant nor any to escape?"],["Ezra",9,15,"O Lord God of Israel, Thou are righteous: for we are left, a remnant that is escaped, as it is this day: behold, we are before Thee in our guiltiness: but we cannot stand before Thee because of this."],["Ezra",10,1,"Now when Ezra had prayed, and when he had made confession, weeping and casting himself before the house of God, there assembled to him out of Israel a very great congregation of men and women and children: for the people wept very bitterly."],["Ezra",10,2,"And Shechaniah the son of Jehiel, one of the sons of Elam, answered and said to Ezra, We have trespassed against our God, and have taken alien women of the peoples of the land: yet now there is hope in Israel concerning this thing."],["Ezra",10,3,"Now therefore let us make a covenant with our God to put away all such women, and such as are born of them, according to the counsel of my lord, and of those who tremble at the commandment of our God; and let it be done according to the law."],["Ezra",10,4,"Arise; for it is thy task: we also will be with thee: be of good courage, and do it."],["Ezra",10,5,"Then Ezra arose, and made the chief priests, the Levites, and all Israel swear that they would do according to this word. And they swore."],["Ezra",10,6,"Then Ezra rose up from before the house of God, and went into the chamber of Johanan the son of Eliashib: and when he came there, he ate no bread, nor drank water: for he mourned because of the transgression of the exiles."],["Ezra",10,7,"And they made proclamation throughout Judah and Jerusalem to all the children of the exile, that they should gather themselves together to Jerusalem;"],["Ezra",10,8,"and that whoever would not come within three days, according to the counsel of the princes and the elders, all his substance should be forfeited, and himself separated from the congregation of the exiles."],["Ezra",10,9,"Then all the men of Judah and Benjamin gathered themselves together to Jerusalem within three days. It was the ninth month, on the twentieth day of the month; and all the people sat in the open place before the house of God, trembling because of this matter, and on account of the great rain."],["Ezra",10,10,"And Ezra the priest stood up, and said to them, You have transgressed, and have taken alien women to increase the guilt of Israel."],["Ezra",10,11,"Now therefore make confession to the Lord God of your fathers, and do his pleasure: and separate yourselves from the peoples of the land, and from the alien women."],["Ezra",10,12,"Then all the congregation answered and said with a loud voice. As thou hast said, so must we do."],["Ezra",10,13,"But the people are many, and it is a time of much rain, and we are not able to stand outside, nor is this a work of one day or two: for we are many who have transgressed in this thing."],["Ezra",10,14,"Let now our rulers of all the congregation stand, and let all those who have taken foreign women in our cities come at appointed times, and with them the elders of every city, and their judges, until the fierce wrath of our God for this matter is turned away from us."],["Ezra",10,15,"Only Jonathan the son of Asahel and Jahaziah the son of Tikvah stood out against this: and Meshullam and Shabbethai the Levite helped them."],["Ezra",10,16,"And the children of the exile did so. And certain chiefs of the fathers' houses after the house of their fathers, and all of them by their names, were separated by Ezra the priest, and they sat down on the first day of the tenth month to examine the matter."],["Ezra",10,17,"And they made an end of the whole matter of the men who had taken foreign women by the first day of the first month."],["Ezra",10,18,"And among the sons of the priests there were found such as had taken foreign women: namely, of the sons of Jeshua the son of Jozadak, and his brothers; Maaseiah, and Eliezer, and Jarib, and Gedaliah."],["Ezra",10,19,"And they gave their hand that they would put away their wives; and being guilty, they offered a ram of the flock for their guilt."],["Ezra",10,20,"And of the sons of Immer; Hanani, and Zebadiah;"],["Ezra",10,21,"and of the sons of Harim, Maaseiah and Elijah, and Shemaiah, and Jehiel, and Uzziah;"],["Ezra",10,22,"and of the sons of Pashur, Elioenai, Maaseiah, Ishmael, Nethaneel, Jozabad, and Elasah;"],["Ezra",10,23,"and of the Levites, Jozabad, and Simi, and Kelaiah, (the same is Kelita,) Pethahiah, Judah, and Eliezer;"],["Ezra",10,24,"and of the singers, Eliashib; and of the gatekeepers, Shallum, and Telem, and Uri;"],["Ezra",10,25,"and of Israel: of the sons of Parosh, Ramiah, and Jizziiah, and Malchijah, and Mijamin, and Eleazar, and Malchijah, and Benaiah;"],["Ezra",10,26,"and of the sons of Elam, Mattaniah, Zechariah, and Jehiel, and Abdi, and Jeremoth, and Elijah;"],["Ezra",10,27,"and of the sons of Zattu, Elioenai, Eliashib. Mattaniah, and Jeremoth, and Zabad, and Aziza;"],["Ezra",10,28,"and of the sons of Bebai, Jehohanan, Hananiah, Zabbai, and Athlai;"],["Ezra",10,29,"and of the sons of Bani, Meshullam, Maluch, and Adaiah, Jashub, and Sheal, and Ramoth;"],["Ezra",10,30,"and of the sons of Pahath-moab, Adna, and Chelal, Benaiah, Maaseiah, Mattaniah, Bezaleel, and Binnui, and Manasseh;"],["Ezra",10,31,"and of the sons of Harim, Eliezer, Isshiah, Malchijah, Shemaiah, Simeon,"],["Ezra",10,32,"Benjamin, Maluch, Shemariah;"],["Ezra",10,33,"of the sons of Hashum, Mattenai, Mattathah, Zabad, Eliphelet, Jeremai, Manasseh, Shimei;"],["Ezra",10,34,"of the sons of Bani, Maadai, Amram, and Uel,"],["Ezra",10,35,"Benaiah, Bedeiah, Chelluh,"],["Ezra",10,36,"Vaniah, Meremoth, Eliashib,"],["Ezra",10,37,"Mattaniah, Mattenai, and Jaasau,"],["Ezra",10,38,"and Bani, and Binnui, Shimei,"],["Ezra",10,39,"Shelemiah, and Nathan, and Adaiah,"],["Ezra",10,40,"Machnadebai, Shashai, Sharai,"],["Ezra",10,41,"Azareel, and Shelemiah, Shemariah,"],["Ezra",10,42,"Shallum, Amariah, and Joseph."],["Ezra",10,43,"Of the sons of Nebo, Joel, Mattithiah, Zabad, Zebina, Jadau, and Jeiel, Benaiah."],["Ezra",10,44,"All these had married foreign women: and some of them had wives by whom they had children."]]);
